# Find statistical outliers across layers for the same parameter role
import pickle, re, numpy as np
stats = pickle.load(open('/work/tensor_stats.pkl','rb'))
groups = {}
for n, s, nrm, mx in stats:
    key = re.sub(r'\.\d+\.', '.', n)
    groups.setdefault(key, []).append((n, nrm, mx))
for key, items in sorted(groups.items()):
    if len(items) < 4: continue
    norms = np.array([i[1] for i in items])
    med = np.median(norms)
    for n, nrm, mx in items:
        if abs(nrm - med) > 0.35 * med:
            print('OUTLIER', n, f'norm={nrm:.2f} med={med:.2f} max={mx:.3f}')
